 CMakeLists.txt               |  1 +
 src/kded/CMakeLists.txt      |  1 +
 src/kded/bluedevildaemon.cpp | 34 ++++++++++++++++++++++++++++++++++
 src/kded/bluedevildaemon.h   |  1 +
 5 files changed, 38 insertions(+)

