diff --git a/src/kded/bluedevildaemon.cpp b/src/kded/bluedevildaemon.cpp
index 2fdcede2..a0c12140 100644
--- a/src/kded/bluedevildaemon.cpp
+++ b/src/kded/bluedevildaemon.cpp
@@ -15,10 +15,15 @@
 #include "obexftp.h"
 #include "version.h"

+#include <QAction>
+#include <QDBusConnection>
+#include <QDBusMessage>
 #include <QDBusMetaType>
+#include <QDBusPendingCall>
 #include <QTimer>

 #include <KAboutData>
+#include <KGlobalAccel>
 #include <KLocalizedString>
 #include <KPluginFactory>

@@ -64,6 +69,14 @@ BlueDevilDaemon::BlueDevilDaemon(QObject *parent, const QList<QVariant> &)
     d->m_timer.setSingleShot(true);
     connect(&d->m_timer, &QTimer::timeout, this, &BlueDevilDaemon::stopDiscovering);

+    auto toggleAction = new QAction(this);
+    toggleAction->setObjectName(QStringLiteral("Toggle Bluetooth"));
+    toggleAction->setText(i18nc("@action global shortcut", "Toggle Bluetooth"));
+    toggleAction->setProperty("componentName", QStringLiteral("bluedevil"));
+    toggleAction->setProperty("componentDisplayName", i18nc("@title name of the global shortcuts category", "Bluetooth"));
+    KGlobalAccel::setGlobalShortcut(toggleAction, QKeySequence(Qt::Key_Bluetooth));
+    connect(toggleAction, &QAction::triggered, this, &BlueDevilDaemon::toggleBluetooth);
+
     KAboutData aboutData(QStringLiteral("bluedevildaemon"),
                          i18n("Bluetooth Daemon"),
                          QStringLiteral(BLUEDEVIL_VERSION_STRING),
@@ -209,6 +222,27 @@ void BlueDevilDaemon::operationalChanged(bool operational)
     }
 }

+void BlueDevilDaemon::toggleBluetooth()
+{
+    if (!d->m_manager->isOperational() || (!d->m_manager->isBluetoothBlocked() && d->m_manager->adapters().isEmpty())) {
+        return;
+    }
+
+    const bool enable = !d->m_manager->isBluetoothOperational();
+
+    d->m_manager->setBluetoothBlocked(!enable);
+    for (const BluezQt::AdapterPtr &adapter : d->m_manager->adapters()) {
+        adapter->setPowered(enable);
+    }
+
+    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                      QStringLiteral("/org/kde/osdService"),
+                                                      QStringLiteral("org.kde.osdService"),
+                                                      QStringLiteral("bluetoothEnabledChanged"));
+    msg.setArguments({enable});
+    QDBusConnection::sessionBus().asyncCall(msg);
+}
+
 void BlueDevilDaemon::obexOperationalChanged(bool operational)
 {
     qCDebug(BLUEDEVIL_KDED_LOG) << "ObexManager operational changed" << operational;
diff --git a/src/kded/bluedevildaemon.h b/src/kded/bluedevildaemon.h
index 2d428275..a57616da 100644
--- a/src/kded/bluedevildaemon.h
+++ b/src/kded/bluedevildaemon.h
@@ -62,6 +62,7 @@ private Q_SLOTS:
     void initObexJobResult(BluezQt::InitObexManagerJob *job);

     void operationalChanged(bool operational);
+    void toggleBluetooth();
     void obexOperationalChanged(bool operational);

     void agentRegisted(BluezQt::PendingCall *call);
